@app.get(f"{settings.API_PREFIX}/health", tags=["health"])
def health():
    return {
        "status": "ok",
        "version": settings.APP_VERSION,
        "revision": settings.APP_REVISION,
        "build_date": settings.APP_BUILD_DATE,
    }


def _check_db() -> bool:
    """Blocking DB liveness probe. Run in a threadpool — never on the loop."""
    try:
        with engine.connect() as conn:
            conn.execute(text("SELECT 1"))
        return True
    except Exception:
        return False


@app.get(f"{settings.API_PREFIX}/health/ready", tags=["health"])
async def health_ready():
    # --- database check -------------------------------------------------------
    # engine.connect() is blocking and can stall for the pool-checkout/connect
    # timeout when Postgres is slow or down — exactly when readiness probes
    # fire most. Offload to the threadpool so it never blocks the event loop
    # (which would stall every in-flight request and SSE stream on this worker).
    db_ok = await run_in_threadpool(_check_db)

    body: dict = {
        "status": "ok" if db_ok else "error",
        "db": "ok" if db_ok else "unavailable",
    }

    # --- redis check (only when configured) -----------------------------------
    if settings.redis_enabled:
        redis_ok = await ping_redis()
        body["redis"] = "ok" if redis_ok else "unavailable"
        if not redis_ok:
            body["status"] = "error"

    if body["status"] == "error":
        return JSONResponse(status_code=503, content=body)
    return body

# Family Tree — full web application stack, built from source.
#
# PostgreSQL is NOT part of this stack (as is common for e.g. Unraid apps):
# run your own Postgres and point the backend at it via the .env file
# (POSTGRES_* values or a full DATABASE_URL). For development,
# `docker compose -f docker-compose.dev.yml up -d db` starts a local Postgres.
# Redis is also external — set REDIS_URL in your .env to enable it (optional).
#
# Configure via a .env file next to this one (see .env.example). The headline
# settings:
#   UI_PORT        host port the web UI is served on
#   APP_DATA_PATH  host path for application data (backend appdata: exports, logs)
#   DATA_PATH      host path for the "real" data (member photos, gallery media)
#   POSTGRES_*     where to reach your PostgreSQL instance
#   REDIS_URL      optional external Redis (leave unset to run without Redis)
#
# Every documented backend setting (see backend/app/core/config.py and
# .env.example) is listed in the backend service's `environment:` below — a
# .env value only reaches the container if its variable is listed there too.

services:
  backend:
    build: ./backend
    environment:
      ENVIRONMENT: production
      SECRET_KEY: ${SECRET_KEY:?Set SECRET_KEY in your .env}
      DATABASE_URL: ${DATABASE_URL:-}
      POSTGRES_HOST: ${POSTGRES_HOST:?Set POSTGRES_HOST (or DATABASE_URL) in your .env}
      POSTGRES_PORT: ${POSTGRES_PORT:-5432}
      POSTGRES_USER: ${POSTGRES_USER:-familytree}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:-familytree}
      POSTGRES_DB: ${POSTGRES_DB:-familytree}
      DB_POOL_SIZE: ${DB_POOL_SIZE:-20}
      DB_MAX_OVERFLOW: ${DB_MAX_OVERFLOW:-10}
      DB_POOL_RECYCLE: ${DB_POOL_RECYCLE:-1800}
      DATA_PATH: /data
      APP_DATA_PATH: /appdata
      FRONTEND_URL: ${FRONTEND_URL:-http://localhost:${UI_PORT:-8080}}
      CORS_ORIGINS: ${CORS_ORIGINS:-http://localhost:${UI_PORT:-8080}}
      ALLOW_SELF_REGISTRATION: ${ALLOW_SELF_REGISTRATION:-false}
      FIRST_ADMIN_USERNAME: ${FIRST_ADMIN_USERNAME:-admin}
      FIRST_ADMIN_PASSWORD: ${FIRST_ADMIN_PASSWORD:-}
      FIRST_ADMIN_EMAIL: ${FIRST_ADMIN_EMAIL:-admin@example.com}
      AUTHENTIK_CLIENT_ID: ${AUTHENTIK_CLIENT_ID:-}
      AUTHENTIK_CLIENT_SECRET: ${AUTHENTIK_CLIENT_SECRET:-}
      AUTHENTIK_DISCOVERY_URL: ${AUTHENTIK_DISCOVERY_URL:-}
      AUTHENTIK_SCOPES: ${AUTHENTIK_SCOPES:-openid email profile}
      AUTHENTIK_AUTO_CREATE_USERS: ${AUTHENTIK_AUTO_CREATE_USERS:-true}
      AUTHENTIK_ADMIN_GROUP: ${AUTHENTIK_ADMIN_GROUP:-family-tree-admins}
      REDIS_URL: ${REDIS_URL:-} # optional external Redis; leave unset to disable
      WORKERS: ${WORKERS:-1} # uvicorn worker processes; WORKERS > 1 requires REDIS_URL
    volumes:
      - ${DATA_PATH:-./data}:/data
      - ${APP_DATA_PATH:-./appdata}/backend:/appdata
    healthcheck:
      test:
        [
          "CMD-SHELL",
          'python -c "import urllib.request; urllib.request.urlopen(''http://localhost:8000/api/health/ready'')"',
        ]
      interval: 10s
      timeout: 5s
      retries: 5
      start_period: 30s
    restart: unless-stopped

  frontend:
    build:
      context: .
      dockerfile: frontend/Dockerfile
    depends_on:
      backend:
        condition: service_healthy
    ports:
      - "${UI_PORT:-8080}:8080"
    restart: unless-stopped

